import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static long powerMod(long base, long exp) {
        if (exp == 0) return 1;
        long result = powerMod(base, exp / 2);
        result = (result * result) % MOD;
        if (exp % 2 == 1) {
            result = (result * base) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(powerMod(p, p - 1));
        } else if (k == 1) {
            System.out.println(powerMod(p, p));
        } else {
            long current = k;
            long count = 1;
            while (current != 1) {
                current = (current * k) % p;
                count++;
            }
            long exponent = (p - 1) / count;
            System.out.println(powerMod(p, exponent));
        }
        sc.close();
    }
}
